using System;
using System.Runtime.InteropServices;
using System.Windows.Forms;

namespace Nemoviz_Book_Reader
{
    public partial class Form1 : Form
    {
        [DllImport("libmpv-2.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr mpv_create();

        [DllImport("libmpv-2.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern int mpv_initialize(IntPtr ctx);

        [DllImport("libmpv-2.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern void mpv_terminate_destroy(IntPtr ctx);

        [DllImport("libmpv-2.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern int mpv_set_property_string(IntPtr ctx, string name, string data);

        [DllImport("libmpv-2.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern int mpv_command(IntPtr ctx, IntPtr args);

        private IntPtr mpvHandle = IntPtr.Zero;
        private bool isPlaying = false;

        private Button btnOpen;
        private Button btnPlayPause;
        private TrackBar trackProgress;
        private Label lblTitle;

        public Form1()
        {
            InitializeComponent();
            BuildUI();
            InitializeMpv();
            this.KeyPreview = true;
            this.KeyDown += Form1_KeyDown;
        }

        private void BuildUI()
        {
            this.Text = "Nemoviz Book Reader";
            this.Width = 500;
            this.Height = 200;

            lblTitle = new Label();
            lblTitle.Text = "Nije otvorena nijedna knjiga";
            lblTitle.Dock = DockStyle.Top;
            lblTitle.Height = 30;
            lblTitle.TextAlign = System.Drawing.ContentAlignment.MiddleLeft;
            lblTitle.AccessibleName = "Naslov knjige";

            btnOpen = new Button();
            btnOpen.Text = "Otvori";
            btnOpen.Width = 100;
            btnOpen.Height = 35;
            btnOpen.Location = new System.Drawing.Point(10, 40);
            btnOpen.AccessibleName = "Otvori datoteku";
            btnOpen.Click += BtnOpen_Click;

            btnPlayPause = new Button();
            btnPlayPause.Text = "Play";
            btnPlayPause.Width = 100;
            btnPlayPause.Height = 35;
            btnPlayPause.Location = new System.Drawing.Point(120, 40);
            btnPlayPause.AccessibleName = "Play ili pauza";
            btnPlayPause.Enabled = false;
            btnPlayPause.Click += BtnPlayPause_Click;

            trackProgress = new TrackBar();
            trackProgress.Dock = DockStyle.Bottom;
            trackProgress.Height = 45;
            trackProgress.Minimum = 0;
            trackProgress.Maximum = 1000;
            trackProgress.AccessibleName = "Napredak reprodukcije";

            this.Controls.Add(lblTitle);
            this.Controls.Add(btnOpen);
            this.Controls.Add(btnPlayPause);
            this.Controls.Add(trackProgress);
        }

        private void Form1_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyCode)
            {
                case Keys.Space:
                    if (btnPlayPause.Enabled)
                        BtnPlayPause_Click(null, null);
                    e.Handled = true;
                    break;
                case Keys.O:
                    if (e.Control)
                        BtnOpen_Click(null, null);
                    e.Handled = true;
                    break;
            }
        }

        private void BtnOpen_Click(object sender, EventArgs e)
        {
            using (OpenFileDialog ofd = new OpenFileDialog())
            {
                ofd.Filter = "Audio datoteke|*.mp3;*.ogg;*.flac;*.m4a;*.wav;*.opus;*.aac|Sve datoteke|*.*";
                ofd.Title = "Odaberi audio knjigu";
                if (ofd.ShowDialog() == DialogResult.OK)
                {
                    lblTitle.Text = System.IO.Path.GetFileName(ofd.FileName);
                    LoadFile(ofd.FileName);
                }
            }
        }

        private void LoadFile(string path)
        {
            MpvCommand("loadfile", path);
            btnPlayPause.Enabled = true;
            btnPlayPause.Text = "Pauza";
            isPlaying = true;
        }

        private void BtnPlayPause_Click(object sender, EventArgs e)
        {
            MpvCommand("cycle", "pause");
            isPlaying = !isPlaying;
            btnPlayPause.Text = isPlaying ? "Pauza" : "Play";
        }

        private void MpvCommand(params string[] args)
        {
            if (mpvHandle == IntPtr.Zero) return;

            IntPtr[] ptrs = new IntPtr[args.Length + 1];
            for (int i = 0; i < args.Length; i++)
                ptrs[i] = Marshal.StringToHGlobalAnsi(args[i]);
            ptrs[args.Length] = IntPtr.Zero;

            GCHandle handle = GCHandle.Alloc(ptrs, GCHandleType.Pinned);
            try
            {
                mpv_command(mpvHandle, handle.AddrOfPinnedObject());
            }
            finally
            {
                handle.Free();
                foreach (var ptr in ptrs)
                    if (ptr != IntPtr.Zero)
                        Marshal.FreeHGlobal(ptr);
            }
        }

        private void InitializeMpv()
        {
            try
            {
                mpvHandle = mpv_create();
                if (mpvHandle == IntPtr.Zero) return;
                mpv_initialize(mpvHandle);
                mpv_set_property_string(mpvHandle, "audio-display", "no");
            }
            catch (Exception ex)
            {
                MessageBox.Show("Greška: " + ex.Message);
            }
        }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            if (mpvHandle != IntPtr.Zero)
                mpv_terminate_destroy(mpvHandle);
            base.OnFormClosing(e);
        }
    }
}
